PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3id.org/serp/2.1/reference#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?tsid WHERE {
  ?zone a brick:Basement ; rdfs:label ?label .
  ?point brick:hasSubProperty brick:Occupancy ; brick:pointOf ?zone .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?point ref:hasExternalReference [] }
} LIMIT 50

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?label ?type WHERE {
  ?z rdfs:label ?label ; a ?type .
  FILTER (LCASE(?label) LIKE "%basement%")
} LIMIT 20

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?uri ?label ?type WHERE {
  ?uri rdfs:label ?label .
  ?uri a ?type .
} LIMIT 60

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
} LIMIT 80

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?label ?type WHERE {
  ?s a ?type .
  FILTER (str(?type) = "https://brickschema.org/schema/Brick#Zone")
} LIMIT 60

PREFIX ref: <http://w3id.org/serp/2.1/reference#>
SELECT ?p ?class ?uri ?tsid WHERE {
  ?p ref:hasTimeseriesId ?tsid .
  ?p a ?class .
  ?p brick:pointOf ?zone .
}
